import json,hashlib
from pathlib import Path
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[3];K=Path(__file__).resolve().parent;B=K/'batches/edition-1';S=R/'projects/site';now=datetime.now(timezone.utc).isoformat()
q=json.loads((K/'queue.json').read_text());assert q['active_batch'] is None;assert not (B/'batch.json').exists();B.mkdir(parents=True,exist_ok=True)
rows=[(11,'a-bloom-in-the-small-garden','A bloom in the small garden','The two short poems find resilience in tending a terrace garden and in a mother making something nourishing from an egg. One modest bloom on a potted vine represents the first poem and their shared ordinary care, without combining flowers and breakfast into a prop display.','Horizontal3:2 transparent watercolor and sparse pencil. Close side view of a modest potted flowering vine on an ordinary terrace. One small cluster of papery rose-magenta bougainvillea bracts catches gentle daylight among a few uneven green leaves; a slender woody stem rises naturally from a partly cropped terracotta pot at lower left and leans toward upper centre. Some leaves have fallen near the pot. Pale unadorned parapet behind and generous warm ivory open space at right. No ornate garden, abundance of flowers, spring explosion, butterflies, text, people, extra pots or symmetrical arrangement. Soft edges, selective small pencil marks and believable stem connections.','watercolor and pencil'),(13,'rain-held-for-a-moment','Rain held for a moment','The speaker tries to catch rain in words while some drops escape. A close view of water gathering then slipping from an umbrella edge keeps that fleeting attention without illustrating every stanza or inventing a crying face.','Horizontal3:2 muted blue-grey gouache with loose wet watercolor. Tight asymmetrical close view of the gently sloping outer edge of a plain indigo cloth umbrella cropped across upper left. A few small water beads gather along its hem; two falling droplets below, irregular and understated. Soft out-of-focus green garden suggested in broad washes behind, pale grey rainy air occupying right half. Fabric is under plausible tension over one barely suggested rib, no impossible canopy geometry, no metallic shine. No person, hands, eyes, writing, lettering, umbrella pattern, spectacular rain streaks or jewel-like macro droplets. Ordinary diffuse wet-day light, quiet painterly marks.','gouache and watercolor'),(14,'the-wing-that-will-not-mend','The wing that will not mend','The poem carries an unrepairable wooden parrot wing before the speaker chooses sunlight. A simple damaged wooden toy holds the weight of attempted repair while a small ordinary patch of light leaves the ending open. It is a symbolic object, not an injured live bird.','Horizontal3:2 graphite and muted ochre-green gouache on ivory paper. A small plainly carved wooden parrot toy rests stably on an unadorned wooden shelf at left, seen in clear three-quarter side view. Recognizable simple curved beak, one painted dark eye and rounded body with faded green paint. The near-side flat carved wing has broken away at a small exposed pale wooden joint; the detached wing lies flat immediately beside the body on the shelf, clearly separate and identifiable. No dangling anatomy, no flesh or blood, no realistic feathers, no elaborate traditional craft pattern or documentary cultural attribution. Its tail and simple flat base support it naturally. A soft rectangular daylight patch on the otherwise plain wall to right, no theatrical spotlight. Sparse pencil marks, restrained detail, broad negative space. No glue brand, bottle, cage, text, hands or people.','graphite and gouache')]
items=[]
for pid,ident,title,reason,scene,medium in rows:
 p=S/f'content/editions/issue-01/poem-{pid}.json';d=json.loads(p.read_text());snapshot=B/p.name;snapshot.write_bytes(p.read_bytes())
 prompt=f'Use case: illustration-story. Original horizontal3:2 literary artwork for Kabita Live Issue1. Human Natural in Poetic Natural mode. Preserve the selected expressive medium. This is an interpretation, not documentary evidence.\nEmotional anchor: {reason}\nScene: {scene}\nAnti-optimization diagnosis: avoid staged symmetry, equal detail everywhere, theatrical light, decorative clutter and cosmetic distress. Causal materials and contact, selective marks, ordinary illumination and emotional ambiguity. No identifiable people, portraits, readable text, logos, signatures or watermarks. Opaque ivory-paper background.\nFull poem context only; never render words: {d["title"]} by {d["author"]}\n{d["text"]}\n'
 pp=B/f'{ident}-prompt.txt';pp.write_text(prompt);items.append(dict(id=ident,edition=1,poem_id=pid,title=title,rationale=reason,status='pending',prompt=str(pp.relative_to(R)),poem_source=str(p.relative_to(R)),poem_evidence=str(snapshot.relative_to(R)),poem_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),output=f'kb/artifacts/artwork/edition-art-rollout-2026-10-04/edition-1/{ident}/v1.png',attempts=[],medium_label=medium,independent=False))
plain=[dict(poem_id=10,rationale='The critique of enforced self-sacrifice stays text-led without literal self-harm imagery.',status='pending'),dict(poem_id=20,rationale='Unsaid words and the need to listen deserve space for the voice rather than an invented mourner.',status='pending'),dict(poem_id=26,rationale='Ageing and family photographs remain in the poet’s language; no invented parental faces or clichéd elderly figure.',status='pending')]
for p in (S/'content/editions/issue-01').glob('poem-*.json'):(B/p.name).write_bytes(p.read_bytes())
b=dict(edition=1,status='planned',created_at=now,poems_read=sorted(json.loads(p.read_text())['id'] for p in (S/'content/editions/issue-01').glob('poem-*.json')),direction='November attends to small forms of care and release: a terrace bloom, rain slipping from an umbrella and a wooden wing that will not mend. Watercolor, gouache and graphite shift between growth, passing weather and material weight. Self-sacrifice, listening and ageing receive text-led openings.',items=items,text_led=plain,independent=False)
(B/'batch.json').write_text(json.dumps(b,ensure_ascii=False,indent=2)+'\n');ed=next(x for x in q['editions'] if x['edition']==1);ed.update(status='planned',artworks=[i['id'] for i in items],text_led=[i['poem_id'] for i in plain],batch=str((B/'batch.json').relative_to(R)),direction=b['direction']);q['active_batch']=dict(id='edition-1',owner='current-chat-assistant',started_at=now,status='running');q['updated_at']=now;(K/'queue.json').write_text(json.dumps(q,ensure_ascii=False,indent=2)+'\n');print('Edition1 planned;19 complete snapshots retained.')
